#!/usr/bin/env node
// Scene geometry data tool.
//   node tools/geometry.cjs build   validate v8/data/scene-geometry.json against the real scenes and regenerate v8/src/scene-geometry-data.js
//   node tools/geometry.cjs check   fail if the JSON is invalid or the generated file is stale
// The studio server calls build() after every save. Scenes are loaded exactly as the game loads them (vm sandbox).
'use strict';
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');
const root=path.resolve(__dirname,'..'),live=path.join(root,'v8');
const dataPath=path.join(live,'data','scene-geometry.json'),generatedPath=path.join(live,'src','scene-geometry-data.js');

// Load SCENES the way index.html does, without a DOM: art, map, scenes, areas + hawaii. World/NYC are added by world-travel
// only in a browser, so they are stubbed here for id validation.
function loadScenes(){
 const context={};context.window=context;context.globalThis=context;vm.createContext(context);
 const run=name=>vm.runInContext(fs.readFileSync(path.join(live,'src',name+'.js'),'utf8'),context,{filename:name+'.js'});
 for(const name of ['art','map','scenes','areas','hawaii','scene-geometry'])run(name);
 context.SCENES.world={id:'world',world:true,width:4096,height:3072};context.SCENES.nyc={id:'nyc'};
 context.V8_AREAS.install(context.V8_HAWAII.defs,context.SCENES);
 return context;
}

function generate(data){
 return ['// GENERATED by tools/geometry.cjs from v8/data/scene-geometry.json - edit with the studio (npm run studio) or by hand, then `npm run geometry:build`.',
  '((root)=>{',
  " 'use strict';",
  ' const data='+JSON.stringify(data)+';',
  ' root.V8_SCENE_GEOMETRY_DATA=Object.freeze(data);if(root!==globalThis)globalThis.V8_SCENE_GEOMETRY_DATA=data;',
  " if(typeof module!=='undefined'&&module.exports)module.exports=data;",
  "})(typeof window==='undefined'?globalThis:window);",''].join('\n');
}

function analyze(){
 const data=JSON.parse(fs.readFileSync(dataPath,'utf8')),context=loadScenes();
 context.V8_GEOMETRY.validate(data,context.SCENES);
 const serialized=JSON.stringify(data,null,1)+'\n',generated=generate(data);
 const same=(file,text)=>fs.existsSync(file)&&fs.readFileSync(file,'utf8').replace(/\r\n/g,'\n')===text;
 return {data,serialized,generated,manifestStale:!same(dataPath,serialized),generatedStale:!same(generatedPath,generated)};
}
function build({quiet=false}={}){
 const a=analyze();
 if(a.manifestStale)fs.writeFileSync(dataPath,a.serialized);
 if(a.generatedStale)fs.writeFileSync(generatedPath,a.generated);
 if(!quiet)console.log(`✔ scene-geometry.json: ${Object.keys(a.data.scenes).length} scene override(s) valid; src/scene-geometry-data.js ${a.generatedStale?'regenerated':'unchanged'}.`);
 return a;
}
function check(){
 const a=analyze(),problems=[];
 if(a.manifestStale)problems.push('scene-geometry.json formatting differs from tools/geometry.cjs output (run `npm run geometry:build`).');
 if(a.generatedStale)problems.push('v8/src/scene-geometry-data.js is out of date (run `npm run geometry:build`).');
 if(problems.length){console.error('✖ Scene geometry check failed.\n'+problems.join('\n'));return false;}
 console.log(`✔ Scene geometry: ${Object.keys(a.data.scenes).length} override(s) valid against the live scenes; data file current.`);
 return true;
}

module.exports={build,check,loadScenes,dataPath,generatedPath};
if(require.main===module){
 const command=process.argv[2];
 try{
  if(command==='build')build();
  else if(command==='check'){if(!check())process.exit(1);}
  else{console.error('Usage: node tools/geometry.cjs build|check');process.exit(2);}
 }catch(error){console.error('✖ '+error.message);process.exit(1);}
}
